<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany};
/** Provides field work order behavior within the WorkIntel application. */ class FieldWorkOrder extends Model{protected $fillable=['uuid','workspace_id','project_id','client_id','work_order_number','title','description','status','priority','scheduled_start_at','scheduled_end_at','due_at','site_name','site_address','latitude','longitude','geofence_radius_meters','instructions','created_by'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['scheduled_start_at'=>'datetime','scheduled_end_at'=>'datetime','due_at'=>'datetime','latitude'=>'decimal:7','longitude'=>'decimal:7'];}/** Handles the assignees operation for the current WorkIntel workflow. */ public function assignees():HasMany{return $this->hasMany(FieldWorkOrderAssignee::class);}/** Handles the events operation for the current WorkIntel workflow. */ public function events():HasMany{return $this->hasMany(FieldWorkOrderEvent::class);}/** Handles the files operation for the current WorkIntel workflow. */ public function files():HasMany{return $this->hasMany(FieldFile::class);}/** Handles the project operation for the current WorkIntel workflow. */ public function project():BelongsTo{return $this->belongsTo(Project::class);}/** Handles the client operation for the current WorkIntel workflow. */ public function client():BelongsTo{return $this->belongsTo(Client::class);}}
